insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-library-check-run-on-publish-s688','decision','The Library check run checks each page it publishes, with the one engine','SkyLinnet (S688), #3560 part 2: library-publish.yml checks every page it published and every piece waiting on the Public Library with no check since its page changed, through scripts/a11y.js (Light and Dark). One cpl_library_checks row per page: current url and key, division settings, findings, a report on Pages. A failed page waits for a new version.',array['library','public-library','a11y-gate'],'proposed','#3560 COBIx comment 7025524965','SkyLinnet (S688)',null,'SkyLinnet (S688)',date '2026-11-20'),
('d-library-run-lists-by-guarded-update-s688','decision','The check run lists a passing Public piece with a guarded update','SkyLinnet (S688), #3560 part 2: a piece with publish_target public whose check passed this run is listed by the service role writing the columns cpl_library_set_public() writes, guarded on the record as read, on the url and version checked, and on a pass no older than page_changed_at. set_public refuses the service key at its first gate.',array['library','public-library','a11y-gate'],'proposed','#3560 COBIx comment 7025524965','SkyLinnet (S688)',null,'SkyLinnet (S688)',date '2026-11-20'),
('d-library-footer-from-check-s688','decision','Every Library page carries one accessibility line from its own check record','SkyLinnet (S688), #3560 part 2: one marked line before the Ask Sierra script, from the latest check at the page''s key and url after its last change; none or a fail reads Not yet certified. The run writes the pass line before checking, so the page checked is the page served, and rewrites every page''s line each run. The words report linked carry the link.',array['library','public-library','a11y-gate'],'proposed','#3560 COBIx comment 7015158851','SkyLinnet (S688)',null,'SkyLinnet (S688)',date '2026-11-20'),
('d-library-check-after-page-change-s688','decision','A Library check counts only when it ran after the page last changed','SkyLinnet (S688), #3560 part 2: cpl_library.page_changed_at, stamped by a trigger on any url or version change, closes the relabel limit (every version shares one url). set_public counts a pass only at or after it, and a listed version change always unlists, replacing the version-branch exception in d-library-new-page-unlists-s687. The check run relists on a pass.',array['library','public-library','a11y-gate'],'proposed','#3572 COBIx comment 7022946691','SkyLinnet (S688)',null,'SkyLinnet (S688)',date '2026-11-20'),
('d-library-tab-precheck-url-s688','decision','The Library tab''s pre-check matches the url and the page''s last change','SkyLinnet (S688), #3560 part 2: library.js latestCheck reads a page''s newest check per version key and url, and no older than page_changed_at, so after a url move or a relabel the card offers no listing on an old pass. A waiting piece whose check failed says so, with the findings count and the report.',array['library','public-library','a11y-gate'],'proposed','#3572 COBIx comment 7023899407','SkyLinnet (S688)',null,'SkyLinnet (S688)',date '2026-11-20'),
('d-library-list-needs-typed-summary-s688','decision','The check run lists only a piece holding a public summary a person typed','SkyLinnet (S688), second read of #3581: the check run lists a passing Public piece only when it already holds a public_summary a person typed. It never copies the internal summary or the title. Otherwise the piece waits, and the card says it needs a public summary and to press Publish to Public Library to add one.',array['library','public-library','a11y-gate'],'proposed','#3581 S688 conductor second read','SkyLinnet (S688)',null,'SkyLinnet (S688)',date '2026-11-20'),
('d-library-footer-pass-only-on-own-check-s688','decision','A Library page''s line shows a pass only from its own page''s check','SkyLinnet (S688), second read of #3581: the footer line prints a pass only for a page whose check row a run wrote at its current key, url and page_changed_at. A page the run wrote but did not check (one --finish left for the next run) reads Not yet certified. Content changed at the same url and version is the known limit a content hash closes.',array['library','public-library','a11y-gate'],'proposed','#3581 S688 conductor second read','SkyLinnet (S688)',null,'SkyLinnet (S688)',date '2026-11-20')
on conflict (slug) do nothing;

select count(*) as rows from public.cpl_memory where author='SkyLinnet (S688)' and slug in ('d-library-check-run-on-publish-s688','d-library-run-lists-by-guarded-update-s688','d-library-footer-from-check-s688','d-library-check-after-page-change-s688','d-library-tab-precheck-url-s688','d-library-list-needs-typed-summary-s688','d-library-footer-pass-only-on-own-check-s688');
